m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0864')
ROOT=[dict(id='C0864',meaning='家；住所；共同生活的环境',core='一个家及其中的生活、管理和相互关系',image='economy 管好家里的资源；ecology 把生物的生活环境当作家；monoecious 与 dioecious 问雌雄住一家还是分住两家。',intro='希腊 oîkos 是家、住所，相关 oikía 也是居处。它一条路走向持家、资源安排，成为 economy；另一条路把生物的生活环境当作家，成为 ecology。教区、邻居和全有人居住的世界，又留下 parish、diocese 与 ecumenical 等分支。',forms='oik- 保留希腊拼法；经拉丁转写常成为 oec-，英语还常简化为 ec-。econom- 接管理家计的 oikonom-，ecumen- 接“有人居住的世界”oikoumen-。这些是不同历史词干，不能只认一个固定英语字母块。',branches=[['经济与资源安排','economy、economics、economist、economic、economical、economically、economize、economise、uneconomic、uneconomical、macroeconomics、microeconomics'],['生物的家','ecology、ecological、ecologically、ecologist、ecosystem、ecoregion、paleoecology、palaeoecology、oecology、ecesis'],['堂区与教区','parish、parishioner、parochial、parochialism、diocese、diocesan、archdiocese、oeconomus'],['有人居住的世界','ecumenical、ecumenism、ecumenic、oecumenic'],['雌雄结构住在哪里','monoecious、monoecy、dioecious、dioecy、trioecious、gynomonoecy、andromonoecy、andromonecy、paroecious'],['生活史是否换寄主','autoecious、autoecism、heteroecious、heteroecism、heteroecy、homoecious'],['房屋与周围居民','oikology、oikophobia、perioeci']],contrasts='economic 通常说经济相关，economical 通常说节约；economically 两支都能表达。monoecious 的雌雄同株不等于一朵花两性兼有；trioecious 是三类不同植株。diocese 的开头不是“两”，dioecious 的 di- 才是“两”。oikophobia 的政治用法是评价性比喻，不能当作对某人的临床诊断。',practice='先用 economy、economics、economical 说清经济体系、学科与节约。再想象三张植物照片：雌雄花同株、雄株雌株分开、三类植株并存，分别配 monoecious、dioecious、trioecious。',words=list(family),sources=['https://www.etymonline.com/word/economy','https://www.etymonline.com/word/ecology','https://www.etymonline.com/word/parish','https://www.etymonline.com/word/diocese','https://www.etymonline.com/word/ecumenical','https://www.merriam-webster.com/dictionary/trioecious'])]
shared={'ecology','ecological','ecosystem'}
assert {w['word'] for w in W}==set(family)-shared,(set(family)-shared-{w['word'] for w in W},{w['word'] for w in W}-set(family))
assert len(W)==len({w['word'] for w in W})
assert all(w['word'] in m['owned_words'] for w in W)
for w in W:
 assert len(w['examples'])>=2 and len(w['history'])>=2 and w['ipa'],w['word']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in w['history']),w['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_41_oec.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0864',len(W),'new',len(family),'references',sum(len(w['examples']) for w in W),'examples')
